{"name": "write", "args": {"content": """"Stage 3 programmatic style audit: dark luxury identity, contrast, states, typography, layout."""
import argparse
import asyncio
import sys

from playwright.async_api import async_playwright
sys.path.insert(0, "/checks")
import test_http as http  # noqa: E402
from verifier_s3_visual import my_fixture  # noqa: E402


def lum(rgb):
    def chan(c):
        c = c / 255
        return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4
    r, g, b = rgb
    return 0.2126 * chan(r) + 0.7152 * chan(g) + 0.0722 * chan(b)


def ratio(fg, bg):
    l1, l2 = sorted([lum(fg), lum(bg)], reverse=True)
    return (l1 + 0.05) / (l2 + 0.05)


def parse(color):
    parts = color.replace("rgba", "").replace("rgb", "").strip("() ").split(",")
    return tuple(int(float(p)) for p in parts[:3])


async def main(source):
    http.SOURCE = source
    findings = []
    async with async_playwright() as pw:
        browser = await pw.chromium.launch(headless=True, args=["--no-sandbox"])
        page = await (await browser.new_context(viewport={"width": 1440, "height": 1000})).new_page()
        page.set_default_timeout(8000)

        async def audit(name, cond, detail):
            findings.append((name, bool(cond), detail))
            print(("PASS " if cond else "FAIL ") + name + ("" if cond else " :: " + str(detail)[:200]), flush=True)

        assert http.request("POST", "/_test/reset", my_fixture())[0] == 204
        await page.goto(source)
        await page.evaluate("localStorage.clear()")
        await page.goto(source + "/login")
        await page.get_by_test_id("login-email").fill("ada@example.com")
        await page.get_by_test_id("login-password").fill("correct horse")
        await page.get_by_test_id("login-submit").click()
        await page.get_by_test_id("restaurant-select").select_option("noir")
        await page.get_by_test_id("date-input").fill("2036-09-24")
        await page.get_by_test_id("party-size-input").fill("2")
        bob = http.request("POST", "/auth/login", {"email": "bob@example.com", "password": "correct horse"})[1]["token"]
        http.request("POST", "/reservations", {"restaurant_id": "noir", "table_id": "t3", "starts_at_local": "2036-09-24T19:00", "party_size": 2}, token=bob, key="audit-occ3")
        await page.get_by_test_id("search-button").click()
        await page.get_by_test_id("availability-grid").wait_for(state="visible")
        await page.get_by_test_id("slot-t1-19:00").click()

        t = await page.evaluate("""() => {
          const h1 = document.querySelector('h1'), h2 = document.querySelector('h2'), h3 = document.querySelector('h3');
          const body = getComputedStyle(document.body);
          const pick = el => el ? {size: getComputedStyle(el).fontSize, family: getComputedStyle(el).fontFamily} : null;
          return {h1: pick(h1), h2: pick(h2), h3: pick(h3), body: {size: body.fontSize, family: body.fontFamily, line: body.lineHeight}};
        }""")
        sizes = [float(x["size"].rstrip("px")) for x in (t["h1"], t["h2"], t["h3"], t["body"]) if x]
        await audit("typography: descending scale h1>h2>h3>body", all(sizes[i] > sizes[i + 1] for i in range(len(sizes) - 1)), sizes)
        sans = all("Georgia" not in (x["family"] or "") for x in (t["h1"], t["h2"], t["h3"]) if x)
        await audit("typography: sans headings (no stage-2 serif)", sans, t)
        await audit("typography: body line-height >= 1.4", float(t["body"]["line"].rstrip("px")) / float(t["body"]["size"].rstrip("px")) >= 1.4, t["body"])

        states = await page.evaluate("""() => {
          const grab = sel => {const el = document.querySelector(sel); if (!el) return null;
            const cs = getComputedStyle(el); return {bg: cs.backgroundColor, color: cs.color, border: cs.borderColor, opacity: cs.opacity, cursor: cs.cursor};};
          const r = {};
          for (const b of document.querySelectorAll('button[data-local]')) {
            const k = b.dataset.testid;
            if (b.getAttribute('aria-pressed') === 'true') r.selected = grab('[data-testid="'+k+'"]');
            else if (b.getAttribute('data-available') === 'true' && !r.available) r.available = grab('[data-testid="'+k+'"]');
            else if (b.getAttribute('data-available') === 'false' && !r.unavailable) r.unavailable = grab('[data-testid="'+k+'"]');
          }
          return r;
        }""")
        await audit("states: available, unavailable, selected all present", all(states.get(k) for k in ("available", "unavailable", "selected")), list(states))
        if all(states.get(k) for k in ("available", "unavailable", "selected")):
            await audit("states: visually distinct", len({(v["bg"], v["border"], v["color"]) for v in states.values()}) == 3, states)
            await audit("unavailable cell not clickable-looking", states["unavailable"]["cursor"] == "default" or states["unavailable"]["opacity"] != "1", states["unavailable"])

        c = await page.evaluate("""() => {
          const grab = sel => {const el = document.querySelector(sel); return el ? getComputedStyle(el) : null;};
          const btn = grab('.primary') || grab('button[type=submit]');
          return {body: grab('body'), caption: grab('.capacity') || grab('.search-caption'), btn, notice: grab('.notice')};
        }""")
        body_fg, body_bg = parse(c["body"]["color"]), parse(c["body"]["backgroundColor"])
        await audit("dark background in charcoal family", sum(body_bg) < 240, c["body"]["backgroundColor"])
        await audit("contrast: body text >= 4.5:1", ratio(body_fg, body_bg) >= 4.5, round(ratio(body_fg, body_bg), 2))
        if c["caption"]:
            cap_fg = parse(c["caption"]["color"])
            await audit("contrast: caption/muted text >= 4.5:1", ratio(cap_fg, body_bg) >= 4.5, round(ratio(cap_fg, body_bg), 2))
        if c["btn"]:
            await audit("primary button prominent (filled, differs from page)", parse(c["btn"]["backgroundColor"]) != body_bg, c["btn"]["backgroundColor"])
            await audit("contrast: primary button text >= 4.5:1", ratio(parse(c["btn"]["color"]), parse(c["btn"]["backgroundColor"])) >= 4.5,
                        round(ratio(parse(c["btn"]["color"]), parse(c["btn"]["backgroundColor"])), 2))

        s = await page.evaluate("""() => {
          const card = document.querySelector('.seating-card');
          const field = document.querySelector('.field label');
          const input = document.querySelector('[data-testid=party-size-input]');
          const cs = card ? getComputedStyle(card) : null;
          return {cardRadius: cs && cs.borderRadius, cardBorder: cs && cs.borderStyle,
                  labelVisible: field && getComputedStyle(field).display !== 'none' && field.textContent.trim().length > 0,
                  inputHasLabel: input && !!document.querySelector('label[for=' + input.id + ']')};
        }""")
        await audit("cards: rounded radius + defined border/shadow", s["cardRadius"] not in (None, "0px") and s["cardBorder"] != "none", s)
        await audit("inputs have visible labels", s["labelVisible"] and s["inputHasLabel"], s)

        await page.goto(source)
        await page.keyboard.press("Tab")
        f = await page.evaluate("""() => {const el = document.activeElement; const cs = getComputedStyle(el);
            return {style: cs.outlineStyle, width: cs.outlineWidth, color: cs.outlineColor, tag: el.tagName};}""")
        await audit("focus: visible outline on keyboard focus", f["style"] != "none" and float(f["width"].rstrip("px")) >= 2, f)

        await page.set_viewport_size({"width": 375, "height": 812})
        await page.goto(source)
        await page.get_by_test_id("restaurant-select").select_option("noir")
        await page.get_by_test_id("date-input").fill("2036-09-24")
        await page.get_by_test_id("party-size-input").fill("2")
        await page.get_by_test_id("search-button").click()
        await page.get_by_test_id("availability-grid").wait_for(state="visible")
        await page.get_by_test_id("slot-t1-19:00").click()
        m = await page.evaluate("""() => {
          const grid = getComputedStyle(document.querySelector('[data-testid=availability-grid]'));
          const cells = document.querySelectorAll('button[data-local]');
          const first = cells[0] && cells[0].getBoundingClientRect();
          const second = cells[1] && cells[1].getBoundingClientRect();
          return {cols: grid.gridTemplateColumns.split(' ').length, overflow: document.documentElement.scrollWidth > innerWidth,
                  cellW: first && first.width, stacked: second && first && second.top > first.bottom,
                  inputs: getComputedStyle(document.querySelector('[data-testid=date-input]')).minHeight};
        }""")
        await audit("375px: no horizontal overflow", not m["overflow"], m)
        await audit("375px: seating cards single-column, 4-col time grid fits", m["cols"] == 1 and not m["stacked"] and m["cellW"] and m["cellW"] > 40, m)
        await audit("375px: touch-friendly controls (min-height >= 42px)", float(m["inputs"].rstrip("px")) >= 42, m)

        n = await page.evaluate("""() => {
          const read = sel => {for (const sheet of document.styleSheets) {for (const rule of sheet.cssRules) {
            if (rule.selectorText && rule.selectorText.replace(/\\s/g,'') === sel) return rule.style.cssText;}} return null;};
          return {error: read('.notice.error'), uncertain: read('.notice.uncertain')};
        }""")
        await audit("notices: error and uncertain distinct rule styling", n["error"] and n["uncertain"] and n["error"] != n["uncertain"], n)

        await browser.close()
    bad = [f for f in findings if not f[1]]
    print(f"\n==== {len(findings) - len(bad)}/{len(findings)} Stage 3 style-audit checks passed ====", flush=True)
    for name, _, detail in bad:
        print("FAILED:", name, "::", str(detail)[:300], flush=True)
    if bad:
        raise SystemExit(1)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--source", required=True)
    asyncio.run(main(parser.parse_args().source))", "filePath": "/tmp/opencode/s3checks/style_audit_s3.py"}, "tool_call_id": "call_721b0f35681e45fea7c15e57"}

